// reproduce.js
// 1) npm install express compression puppeteer lighthouse
// 2) run with node reproduce.js
const express = require('express');
const compression = require('compression');
const puppeteer = require('puppeteer');
const lighthouse = require('lighthouse');
(async () => {
  // 1. Start an Express server with gzip compression
  const app = express();
  app.use(compression());
  app.get('/api/blob', (req, res) => {
    // generate a ~30KB JSON payload
    const payload = { items: [] };
    for (let i = 0; i < 30000; i++) payload.items.push(Math.random());
    res.json(payload);
  });
  const server = await new Promise(resolve => {
    const s = app.listen(3000, () => resolve(s));
  });
  console.log('Server running at http://localhost:3000');

  // 2. Launch Chrome and run Lighthouse
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--remote-debugging-port=9222']
  });
  const lhr = (await lighthouse('http://localhost:3000', {
    port: 9222,
    output: 'json',
    onlyCategories: ['performance'],
  })).lhr;

  // 3. Print the Enable text compression audit result
  const audit = lhr.audits['uses-text-compression'] || lhr.audits['uses-response-compression'];
  console.log('--- Enable text compression audit ---');
  console.log('Score:', audit.score);
  console.log('Details:', audit.details && audit.details.items);

  await browser.close();
  server.close();
})();
